dialogBox.showDialog();
script.break();
npc.hideFace(3);
npc.showFace(2,duihua);
dialogBox.setType(type_right);
dialogBox.showNpcPortrait(2);
dialogBox.setText(/月瑶/：那也得有人照顾罗堡主啊，紫萱姑娘你照顾罗堡主，我和重楼大哥去水月宫吧。);
